// Elements are kept per job and updated in place, so nodes an observer holds stay attached.
const itemsById = new Map();

function createItem(job) {
  const li = document.createElement('li');
  li.dataset.testid = 'job-item';
  li.dataset.jobId = job.id;

  const name = document.createElement('span');
  const meta = document.createElement('div');
  meta.className = 'meta';
  name.append(document.createTextNode(job.input), meta);

  const status = document.createElement('span');
  status.dataset.testid = 'job-status';
  const progress = document.createElement('span');
  progress.dataset.testid = 'job-progress';
  const result = document.createElement('span');
  result.dataset.testid = 'job-result';

  li.append(name, status, progress, result);
  return { li, meta, status, progress, result };
}

function updateItem(item, job) {
  item.meta.textContent = `attempts ${job.attempts} · ${job.createdAt}`;
  if (item.status.textContent !== job.status) item.status.textContent = job.status;
  item.status.className = 'status-' + job.status;
  const progressText = `${job.progress.completed}/${job.progress.total}`;
  if (item.progress.textContent !== progressText) item.progress.textContent = progressText;
  let resultText = '';
  if (job.status === 'completed' && job.result) resultText = job.result.output;
  else if (job.status === 'failed' && job.error) resultText = job.error;
  if (item.result.textContent !== resultText) item.result.textContent = resultText;
}

function renderJobs(jobs) {
  const seen = new Set();
  jobs.forEach((job, index) => {
    seen.add(job.id);
    let item = itemsById.get(job.id);
    if (!item) {
      item = createItem(job);
      itemsById.set(job.id, item);
    }
    updateItem(item, job);
    // Newest first: move the element only if it is not already at this position.
    if (listEl.children[index] !== item.li) listEl.insertBefore(item.li, listEl.children[index] || null);
  });
  for (const [id, item] of itemsById) {
    if (!seen.has(id)) {
      item.li.remove();
      itemsById.delete(id);
    }
  }
}

